class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums)
        half = n // 2
        prefix = [0] * (n + 1)

        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        count = 0
        total_sum = prefix[n]

        for i in range(n):
            first_sum = prefix[i + half] - prefix[i]
            second_sum = total_sum - first_sum
            if first_sum < second_sum:
                count += 1
        return count

