class Solution:
    def minDeletions(self, nums: list[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i][0] represents the min deletions up to i-th element where last element is not nums[i]
        # dp[i][1] represents the min deletions up to i-th element where last element is nums[i]
        dp = [[0] * 2 for _ in range(n)]

        # Initialize for the first element
        dp[0][0] = 0  # delete the first element (no sharp sequence yet)
        dp[0][1] = 1  # keep the first element (sharp sequence of length 1)

        for i in range(1, n):
            # Option 1: delete nums[i], so the sharp sequence remains up to i-1
            dp[i][0] = dp[i-1][0] + 1
            # Option 2: include nums[i] if the previous element in sharp sequence is different
            if nums[i] != nums[i-1]:
                dp[i][1] = dp[i-1][0]  # previous last element was not nums[i-1], so can include nums[i]
            else:
                # previous last element was nums[i-1], so must delete one of them
                dp[i][1] = dp[i-1][0] + 1  # delete nums[i] (since previous was nums[i-1])
            # Also consider the case where previous last element was nums[i-1], and we delete nums[i-1] to include nums[i]
            if i >= 2 and nums[i] == nums[i-2]:
                dp[i][1] = min(dp[i][1], dp[i-2][1] + 1)

        return min(dp[-1][0], dp[-1][1])

