class Solution:
    def rearrangeArray(self, nums: list[int]) -> list[int]:
        ans = []
        freq = defaultdict(int)
        for num in nums:
            freq[num] += 1

        while freq:
            distinct = sorted(freq.keys())
            for num in distinct:
                if freq[num] > 0:
                    ans.append(num)
                    freq[num] -= 1
                    if freq[num] == 0:
                        del freq[num]
        return ans
